mapper.select:
select message.msg_id, f1.from_u as mfrom_u, f1.name as from_name, f1.avatar as from_avatar,
f2.to_u as mto_u, f2.name as to_name, f2.avatar as to_avatar,
msg, status
from message,
(select msg_id, from_u, name, avatar from user, message where message.from_u=user.u_id) as f1,
(select msg_id, to_u, name, avatar from user, message where message.to_u=user.u_id) as f2
where message.msg_id=f1.msg_id and message.msg_id=f2.msg_id

    and f2.to_u=#{to}


    and status=#{status}

order by message.msg_id asc
